def _blocked_cholesky(data: torch.Tensor, output: torch.Tensor) -> torch.Tensor:
    if output.shape[0] == 1:
        _ext.lower_panel_copy_(data, output, 4096)
    else:
        output.copy_(data)
    n = output.shape[-1]
    if output.shape[0] == 1:
        block = 4096
    elif n == 1024:
        block = 256
    else:
        block = 128

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for stage_index, k in enumerate(range(0, n, block)):
            stop = min(k + block, n)
            if output.shape[0] == 1 and k:
                _left_looking_update_(
                    _half_workspace[k:, :k],
                    data[0, k:, k:stop],
                    output[0, k:, k:stop],
                )
            diagonal = output[:, k:stop, k:stop]
            if output.shape[0] == 1:
                factor = _factor_workspace[stage_index : stage_index + 1]
                _ext.panel_cholesky_(
                    diagonal,
                    factor,
                    _factor_info,
                    _factor_solver_workspace,
                )
            else:
                factor = torch.linalg.cholesky_ex(
                    diagonal, check_errors=False
                ).L
            if output.shape[0] != 1:
                diagonal.copy_(factor)
            if stop == n:
                continue

            panel = output[:, stop:, k:stop]
            if output.shape[0] == 1:
                half_panel = _half_workspace[stop:, k:stop]
                if panel.shape[1] <= 4096:
                    _ext.trsm_(factor, panel)
                    _ext.convert_panel_(panel[0], half_panel)
                else:
                    _inverse_workspace.copy_(_identity_workspace)
                    _ext.trsm_(factor, _inverse_workspace.unsqueeze(0))
                    solved_panel = _solve_workspace[: panel.shape[1]]
                    _left_looking_solve_(
                        panel[0],
                        _inverse_workspace.transpose(0, 1),
                        solved_panel,
                    )
                    _ext.emit_solved_panel_(
                        solved_panel, panel[0], half_panel
                    )
            else:
                solved = torch.linalg.solve_triangular(
                    factor,
                    panel.transpose(-2, -1),
                    upper=False,
                ).transpose(-2, -1)
                panel.copy_(solved)
                _ext.fp16_update_(
                    output[:, stop:, stop:], solved.to(torch.float16)
                )
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32

    if output.shape[0] == 1:
        _ext.copy_factor_stack_lower_(_factor_workspace, output)
        return output
    return output.tril_()


def _compute_batch1024(entry) -> None:
    global _batch_trsm_pointers
    global _batch_factor_workspace, _batch1024_factor_view
    global _batch_factor_half_workspace, _batch1024_factor_half_view
    global _batch1024_factor_flag_view, _batch1024_factor_epoch
    data = entry[0]
    output = entry[1]
    output_view = entry[2]
    stages = entry[3]
    rankk_queue = _batch_rankk_queue_for_current_queue()
    factor_launcher = _batch1024_factor_launcher_for_current_queue(
        _batch1024_factor_view,
        _batch1024_factor_half_view,
        _batch1024_factor_flag_view,
        data.shape[0],
    )

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for stage_index, (diagonal, panel, rankk_stage) in enumerate(stages):
            _ext.batch_factor_gather_(
                diagonal,
                _batch_factor_workspace,
                _batch_trsm_pointers,
            )
            _batch1024_factor_epoch += 1
            factor_launcher(
                _batch1024_factor_view,
                _batch1024_factor_view,
                _batch1024_factor_half_view,
                _batch1024_factor_flag_view,
                np.int32(_batch1024_factor_epoch),
            )
            factor = _batch_factor_workspace
            if rankk_stage is None:
                _ext.batch_factor_copy_cuda(factor, diagonal, output)
                continue
            _ext.prepare_batch_factor_and_pointers_cuda(
                factor, diagonal, panel, _batch_trsm_pointers
            )
            panel_row_base = (stage_index + 1) * 256
            _launch_batch1024_panel_dag(
                _batch1024_factor_view,
                _batch1024_factor_half_view,
                output_view,
                (1024 - panel_row_base) // _D256_NB,
                data.shape[0],
            )
            rankk_stage[0](rankk_stage[1], rankk_stage[2], rankk_queue)
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32


_batch1024_output_entry = None


def _run_batch1024(data: torch.Tensor) -> torch.Tensor:
    global _batch_half_panel, _batch_trsm_pointers
    global _batch_factor_workspace, _batch1024_factor_view
    global _batch_factor_half_workspace, _batch1024_factor_half_view
    global _batch1024_factor_flags, _batch1024_factor_flag_view
    global _batch1024_output_entry
    if _batch_factor_workspace is None:
        _batch_factor_workspace = torch.empty_strided(
            (data.shape[0], 256, 256),
            (256 * 256, 1, 256),
            device=data.device,
            dtype=torch.float32,
        )
        _batch1024_factor_view = _as_numba_flat_array(
            _batch_factor_workspace
        )
        _batch_factor_half_workspace = torch.empty(
            (
                data.shape[0],
                _B1024_FACTOR_SIDECAR_TILES,
                _D256_TILE_ELEMENTS,
            ),
            device=data.device,
            dtype=torch.float16,
        )
        _batch1024_factor_half_view = _as_numba_half_array(
            _batch_factor_half_workspace
        )
        _batch1024_factor_flags = torch.zeros(
            data.shape[0] * 2,
            device=data.device,
            dtype=torch.int32,
        )
        _batch1024_factor_flag_view = _as_numba_int32_array(
            _batch1024_factor_flags
        )
    if _batch_trsm_pointers is None:
        _batch_trsm_pointers = torch.empty(
            2 * data.shape[0], device=data.device, dtype=torch.int64
        )
    entry = _batch1024_output_entry
    if entry is None or entry[0] is not data:
        output = torch.empty_like(
            data, memory_format=torch.contiguous_format
        )
        output_view = _as_numba_flat_array(output)
        stages = []
        for k in range(0, 1024, 256):
            stop = k + 256
            diagonal = output[:, k:stop, k:stop]
            panel = output[:, stop:, k:stop]
            if stop == 1024:
                rankk_stage = None
            else:
                trailing = output[:, stop:, stop:]
                panel_pointer = cute_runtime.make_ptr(
                    cutlass.Float32,
                    panel.data_ptr(),
                    cute.AddressSpace.gmem,
                    assumed_align=16,
                )
                output_pointer = cute_runtime.make_ptr(
                    cutlass.Float32,
                    trailing.data_ptr(),
                    cute.AddressSpace.gmem,
                    assumed_align=16,
                )
                rankk_stage = (
                    _batch_rankk[k // 256],
                    panel_pointer,
                    output_pointer,
                )
            stages.append((diagonal, panel, rankk_stage))
        entry = [data, output, output_view, tuple(stages), None]
        _batch1024_output_entry = entry
    graph = entry[4]
    if graph is None:
        _ext.batch_lower_copy_cuda(data, entry[1])
        _compute_batch1024(entry)
        graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(graph):
            _ext.batch_lower_copy_cuda(data, entry[1])
            _compute_batch1024(entry)
        entry[4] = graph
    graph.replay()
    return entry[1]


def custom_kernel(data: input_t) -> output_t:
    global _active_shape, _info, _workspace, _half_workspace
    global _factor_workspace, _factor_info, _factor_solver_workspace
    global _inverse_workspace, _identity_workspace, _solve_workspace
    global _grouped_pool, _grouped_pool_index
    global _batch_half_panel, _batch_trsm_pointers
    global _batch_factor_workspace, _batch_factor_half_workspace
    global _batch_factor_info
    global _g2048_launcher_cache, _g2048_rankk_queue_cache
    global _batch1024_output_entry
    n = data.shape[-1]
    if n == 32:
        return _ext.cholesky32_cuda(data)
    if n == 64:
        return _ext.cholesky64_cuda(data)
    if n == 128:
        return _ext.cholesky128_cuda(data)
    if n == _D256_N and data.shape[0] == 64:
        return _run_d256(data)
    if n == 1024 and data.shape[0] == 60:
        return _run_batch1024(data)
    if n == _B4096_N and data.shape[0] == 2:
        return _run_b4096(data)
    if n >= 32:
        use_grouped = data.shape[0] == 8 and n == 2048
        grouped_block = 256
        use_mixed = n >= 8192 or (n >= 1024 and data.shape[0] >= 16)
        use_dx = n == _DX_N and data.shape[0] == 640
        shape = tuple(data.shape)
        if shape != _active_shape:
            _output_cache.clear()
            _batch1024_output_entry = None
            _g2048_stage_cache.clear()
            _g2048_launcher_cache.clear()
            _g2048_rankk_queue_cache.clear()
            _batch_half_panel = None
            _batch_trsm_pointers = None
            _batch_factor_workspace = None
            _batch_factor_half_workspace = None
            _batch_factor_info = None
            _active_shape = shape
            use_looped = data.shape[0] <= 4 and n >= 1024
            if use_mixed or use_dx:
                _info = None
                _workspace = None
            else:
                _info = torch.empty(
                    data.shape[0], device=data.device, dtype=torch.int32
                )
                if use_looped:
                    lwork = _ext.workspace_size(data)
                    _workspace = torch.empty(
                        lwork, device=data.device, dtype=torch.float32
                    )
                else:
                    _workspace = torch.empty(
                        0, device=data.device, dtype=torch.float32
                    )
            if data.shape[0] == 1 and n >= 8192:
                _half_workspace = torch.empty(
                    (n, n),
                    device=data.device,
                    dtype=torch.float16,
                )
                _factor_workspace = torch.empty_strided(
                    (n // 4096, 4096, 4096),
                    (4096 * 4096, 1, 4096),
                    device=data.device,
                    dtype=torch.float32,
                )
                _factor_info = torch.empty(
                    1, device=data.device, dtype=torch.int32
                )
                factor_lwork = _ext.workspace_size(_factor_workspace[:1])
                _factor_solver_workspace = torch.empty(
                    factor_lwork, device=data.device, dtype=torch.float32
                )
                if n >= 16384:
                    _identity_workspace = torch.eye(
                        4096, device=data.device, dtype=torch.float32
                    )
                    _inverse_workspace = torch.empty_like(
                        _identity_workspace
                    )
                    _solve_workspace = torch.empty(
                        (n - 4096, 4096),
                        device=data.device,
                        dtype=torch.float32,
                    )
                else:
                    _identity_workspace = None
                    _inverse_workspace = None
                    _solve_workspace = None
            else:
                _half_workspace = None
                _factor_workspace = None
                _factor_info = None
                _factor_solver_workspace = None
                _identity_workspace = None
                _inverse_workspace = None
                _solve_workspace = None
            if use_grouped:
                _grouped_pool = []
                for _ in range(4):
                    pooled_output = torch.zeros_like(
                        data, memory_format=torch.contiguous_format
                    )
                    _grouped_pool.append(pooled_output)
                _grouped_pool_index = 0
            else:
                _grouped_pool = None
                _grouped_pool_index = 0
        key = id(data)
        entry = _output_cache.get(key)
        if entry is None or entry[0] is not data:
            from_grouped_pool = False
            if use_grouped and _grouped_pool_index < len(_grouped_pool):
                output = _grouped_pool[_grouped_pool_index]
                pointers = None
                _grouped_pool_index += 1
                from_grouped_pool = True
            elif (
                (use_mixed and data.shape[0] == 1)
                or use_dx
                or use_grouped
            ):
                output = torch.zeros_like(
                    data, memory_format=torch.contiguous_format
                )
            else:
                output = torch.empty_like(
                    data, memory_format=torch.contiguous_format
                )
            if not from_grouped_pool:
                use_looped = data.shape[0] <= 4 and n >= 1024
                if use_mixed or use_dx:
                    pointers = None
                elif use_grouped:
                    pointers = None
                elif not use_looped:
                    step = n * n * data.element_size()
                    pointers = torch.arange(
                        output.data_ptr(),
                        output.data_ptr() + data.shape[0] * step,
                        step,
                        device=data.device,
                        dtype=torch.int64,
                    )
                else:
                    pointers = torch.empty(
                        0, device=data.device, dtype=torch.int64
                    )
            if use_grouped:
                pointers = _ext.grouped_pointer_table_cuda(
                    output, grouped_block
                )
            if use_dx or use_grouped:
                dx_data = _as_numba_flat_array(data)
            else:
                dx_data = None
            if use_dx:
                factor_sidecar = torch.empty(
                    (
                        data.shape[0],
                        _DX_SIDECAR_TILES,
                        _DX_HALF_TILE_ELEMENTS,
                    ),
                    device=data.device,
                    dtype=torch.float16,
                    memory_format=torch.contiguous_format,
                )
                dx_factor_sidecar = _as_numba_half_array(factor_sidecar)
            else:
                factor_sidecar = None
                dx_factor_sidecar = None
            if use_dx or use_grouped:
                dx_output = _as_numba_flat_array(output)
            else:
                dx_output = None
            entry = (
                data,
                output,
                pointers,
                dx_data,
                dx_output,
                factor_sidecar,
                dx_factor_sidecar,
            )
            _output_cache[key] = entry
        else:
            output, pointers = entry[1], entry[2]
        if use_dx:
            _launch_dx(entry[3], entry[4], entry[6], data.shape[0])
            return output.transpose(-2, -1)
        if use_grouped:
            return _grouped_mathdx_cholesky(
                data, output, entry[3], entry[4], pointers
            )
        if use_mixed:
            return _blocked_cholesky(data, output)
        return _ext.direct_cholesky(data, output, pointers, _info, _workspace)
    return torch.linalg.cholesky_ex(data, check_errors=False).L

